// Generates the AE2 sprite registry + CSS from two pinned upstream asset packs:
// AE2 1.12.2 / rv6 (terminal family) and AE2 1.21.10 (modern `states.png`, which
// carries the corner-tab and priority icons missing from the 1.12.2 sheet).
// Run: pnpm --filter @tennantite/textures sync:ae2-sprites
//
// Sources are pinned to one upstream commit each so the generated files are
// reproducible. `--check` re-renders and compares against the committed files.
import { createHash } from "node:crypto";
import { readFileSync, writeFileSync } from "node:fs";
import { fileURLToPath } from "node:url";

// AE2 1.12.2（rv6）：`states.png` 图标与终端家族贴图。
const LEGACY_COMMIT = "724ffaebe3a8ba7d2320431acf03a8c2f6345d9e";
const LEGACY_BASE
  = `https://raw.githubusercontent.com/AE2-UEL/Applied-Energistics-2/${LEGACY_COMMIT}/`
    + "src/main/resources/assets/appliedenergistics2/textures/guis/";

// AE2 1.21.10：标签按钮底与优先级图标（1.12.2 贴图中不存在）。
const MODERN_COMMIT = "f0935a94b490397361e0c08e2bfd27f923af0f23";
const MODERN_BASE
  = `https://raw.githubusercontent.com/AppliedEnergistics/Applied-Energistics-2/${MODERN_COMMIT}/`
    + "src/main/resources/assets/ae2/textures/guis/";

/**
 * 生成名 → 上游文件。生成名经 kebab-case 后即 CSS 变量后缀
 * （`statesModern` → `--mc-ae2-states-modern`）。
*/
const SPRITES = {
  crafting: { base: LEGACY_BASE, file: "crafting.png" },
  inscriber: { base: LEGACY_BASE, file: "inscriber.png" },
  states: { base: LEGACY_BASE, file: "states.png" },
  statesModern: { base: MODERN_BASE, file: "states.png" },
  terminal: { base: LEGACY_BASE, file: "terminal.png" },
};

// `statesModern` → `states-modern`（CSS 变量名保持 kebab-case）。
function cssName(name) {
  return name.replaceAll(/[A-Z]/g, letter => `-${letter.toLowerCase()}`);
}

const ROOT = fileURLToPath(new URL("../", import.meta.url));
const OUT_TS = `${ROOT}src/ae2-sprites.generated.ts`;
const OUT_CSS = `${ROOT}css/ae2-sprites.generated.css`;

const check = process.argv.includes("--check");

async function download(base, path) {
  let lastError;
  for (let attempt = 1; attempt <= 4; attempt += 1) {
    try {
      const response = await fetch(base + path);
      if (!response.ok) {
        throw new Error(`HTTP ${response.status} ${response.statusText}`);
      }
      return new Uint8Array(await response.arrayBuffer());
    }
    catch (error) {
      lastError = error;
      if (attempt < 4) {
        await new Promise(resolve => setTimeout(resolve, attempt * 400));
      }
    }
  }
  throw new Error(`cannot download ${path}`, { cause: lastError });
}

/**
 * PNG 尺寸：直接读 IHDR（宽高为 big-endian uint32，偏移 16 / 20）。
 */
function pngSize(bytes) {
  return {
    height: new DataView(bytes.buffer, bytes.byteOffset).getUint32(20),
    width: new DataView(bytes.buffer, bytes.byteOffset).getUint32(16),
  };
}

function render(entries) {
  const metaLines = entries.map(([name, entry]) => `  ${/^[a-z][\w$]*$/i.test(name) ? name : JSON.stringify(name)}: {
    cssVar: "--mc-ae2-${cssName(name)}",
    height: ${entry.height},
    sha256: ${JSON.stringify(entry.sha256)},
    width: ${entry.width},
  },`);

  const ts = `// Generated by scripts/sync-ae2-sprites.mjs — DO NOT EDIT.
// Source: AE2-UEL/Applied-Energistics-2 (LGPL-3.0) @ ${LEGACY_COMMIT} — 1.12.2 贴图
// Source: AppliedEnergistics/Applied-Energistics-2 (LGPL-3.0) @ ${MODERN_COMMIT} — 1.21.10 贴图
// Textures © the Applied Energistics 2 authors; see LICENSE-ASSETS.md.
// Regenerate: pnpm --filter @tennantite/textures sync:ae2-sprites

export interface Ae2SpriteMeta {
  cssVar: string;
  height: number;
  sha256: string;
  width: number;
}

export const ae2SpriteMeta = {
${metaLines.join("\n")}
} as const;

export type Ae2SpriteName = keyof typeof ae2SpriteMeta;
`;

  const cssLines = entries.map(
    ([name, entry]) => `  --mc-ae2-${cssName(name)}: url("data:image/png;base64,${entry.base64}");`,
  );

  const css = `/*
 * Generated by scripts/sync-ae2-sprites.mjs — DO NOT EDIT.
 * Source: AE2-UEL/Applied-Energistics-2 (LGPL-3.0) @ ${LEGACY_COMMIT} — 1.12.2 贴图
 * Source: AppliedEnergistics/Applied-Energistics-2 (LGPL-3.0) @ ${MODERN_COMMIT} — 1.21.10 贴图
 * Textures © the Applied Energistics 2 authors; see LICENSE-ASSETS.md.
 */
:root {
${cssLines.join("\n")}
}
`;

  return { css, ts };
}

const entries = [];
for (const [name, sprite] of Object.entries(SPRITES)) {
  const bytes = await download(sprite.base, sprite.file);
  const { height, width } = pngSize(bytes);
  entries.push([
    name,
    {
      base64: Buffer.from(bytes).toString("base64"),
      height,
      sha256: createHash("sha256").update(bytes).digest("hex"),
      width,
    },
  ]);
}
entries.sort((a, b) => a[0].localeCompare(b[0]));

const { css, ts } = render(entries);

if (check) {
  let isStale = false;
  for (const [file, expected] of [
    [OUT_TS, ts],
    [OUT_CSS, css],
  ]) {
    let actual = "";
    try {
      actual = readFileSync(file, "utf8");
    }
    catch {
      isStale = true;
      continue;
    }
    if (actual === expected) {
      continue;
    }

    isStale = true;
    console.error(`out of date: ${file}`);
  }
  if (isStale) {
    process.exit(1);
  }
  console.log("AE2 sprites up to date");
}
else {
  writeFileSync(OUT_TS, ts);
  writeFileSync(OUT_CSS, css);
  console.log(`wrote ${SPRITES.size ?? Object.keys(SPRITES).length} AE2 sprites`);
}
